                  "priority": 4,
                  "text": {
                    "$l10n": {
                      "comment": "Body of the infobar shown to Windows 10 users after a crash, prompting them to back up Firefox.",
                      "id": "win10eos-crash-infobar-body",
                      "text": "Firefox noticed your Windows 10 device might be causing problems with your apps. Back up now to keep your Firefox data safe."
                    }
                  },
                  "type": "global"
                },
                "frequency": {
                  "custom": [
                    {
                      "cap": 1,
                      "period": 86400000
                    }
                  ],
                  "lifetime": 7
                },
                "id": "WIN10EOS_CRASH_BACKUP_INFOBAR",
                "priority": 2,
                "targeting": "(source == 'startup' || source == 'newtab') && os.isWindows && os.windowsVersion >= 10 && os.windowsBuildNumber < 22000 && daysSinceLastCrash == 0 && !usesFirefoxSync && backupArchiveEnabled && !'messaging-system-action.infobarBackupEnabledCrashVariant'|preferenceValue && !'browser.backup.scheduled.enabled'|preferenceValue && !'browser.backup.scheduled.user-disabled'|preferenceValue && !hasActiveEnterprisePolicies && !willShowDefaultPrompt && !activeNotifications && !isMajorUpgrade && (currentDate|date - profileAgeCreated) / 3600000 >= 48 && previousSessionEnd",
                "template": "infobar",
                "trigger": {
                  "id": "defaultBrowserCheck"
                }
              }
            }
