        "localizations": {
          "de": {
            "win10-eos-hnt-mobile-body": "Holen Sie sich die gesamte integrierte Privatsphäre von Firefox auf Ihr Smartphone. Einfach den QR-Code scannen, App herunterladen und lossurfen.",
            "win10-eos-hnt-mobile-heading": "Nutzen Sie Firefox unterwegs"
          },
          "fr": {
            "win10-eos-hnt-mobile-body": "Profitez de la confidentialité par défaut de Firefox sur votre téléphone. Scannez le code QR pour télécharger Firefox et commencer à naviguer.",
            "win10-eos-hnt-mobile-heading": "Utilisez Firefox où que vous soyez"
          },
          "id": {
            "win10-eos-hnt-mobile-body": "Nikmati semua fitur privasi bawaan Firefox di ponsel Anda. Cukup pindai kode QR untuk mengunduh dan mulai menjelajah.",
            "win10-eos-hnt-mobile-heading": "Mulai gunakan Firefox saat bepergian"
          },
          "it": {
            "win10-eos-hnt-mobile-body": "Goditi la privacy integrata di Firefox sul tuo smartphone. Scansiona il QR, scarica e inizia a navigare.",
            "win10-eos-hnt-mobile-heading": "Entra al volo su Firefox"
          },
          "ja": {
            "win10-eos-hnt-mobile-body": "Firefox のすべての内蔵プライバシー機能をスマートフォンでも。QR コードをスキャンするだけで、ダウンロードして始められます。",
            "win10-eos-hnt-mobile-heading": "外出先で Firefox"
          },
          "pl": {
            "win10-eos-hnt-mobile-body": "Firefox to pełna, domyślna ochrona prywatności na Twoim telefonie. Zeskanuj kod QR, aby pobrać. Możesz zaczynać.",
            "win10-eos-hnt-mobile-heading": "Firefox – kiedy jesteś w ruchu"
          },
          "ru": {
            "win10-eos-hnt-mobile-body": "Получите встроенную защиту приватности Firefox на телефоне. Просто отсканируйте QR-код, чтобы скачать Firefox и начать пользоваться интернетом.",
            "win10-eos-hnt-mobile-heading": "Пользуйтесь Firefox на ходу"
          },
          "vi": {
            "win10-eos-hnt-mobile-body": "Tận hưởng mọi tính năng riêng tư tích hợp sẵn của Firefox ngay trên điện thoại của bạn. Chỉ cần quét mã QR để tải xuống và bắt đầu duyệt web.",
            "win10-eos-hnt-mobile-heading": "Mang Firefox theo bạn mọi lúc mọi nơi"
          },
          "en-CA": {
            "win10-eos-hnt-mobile-body": "Get all the built-in privacy of Firefox on your phone. Protection is on from the start. Just scan the QR code to download and go.",
