            "win10-eos-hnt-mobile-heading": "Jump in to Firefox on the go"
          },
          "en-US": {
            "win10-eos-hnt-mobile-body": "Get all the built-in privacy of Firefox on your phone. Protection is on from the start. Just scan the QR code to download and go.",
            "win10-eos-hnt-mobile-heading": "Jump in to Firefox on the go"
